solution.Solution.cs:
using System.Globalization;

public record OrderLine(string Item, int Quantity, decimal Price);

public class OrderFormatException(int lineNumber, string problem, Exception? inner = null)
    : Exception($"line {lineNumber}: {problem}", inner)
{
    public int LineNumber { get; } = lineNumber;
}

public static class Orders
{
    public static OrderLine Parse(string line, int lineNumber)
    {
        ArgumentNullException.ThrowIfNull(line);
        string[] parts = line.Split(';');
        if (parts.Length != 3) throw new OrderFormatException(lineNumber, "expected 3 fields");
        string item = parts[0].Trim();
        if (item.Length == 0) throw new OrderFormatException(lineNumber, "missing item");

        int quantity;
        try
        {
            quantity = int.Parse(parts[1].Trim(), NumberStyles.None, CultureInfo.InvariantCulture);
        }
        catch (Exception e) when (e is FormatException or OverflowException)
        {
            throw new OrderFormatException(lineNumber, "bad quantity", e);
        }
        if (quantity < 1 || quantity > 1000) throw new OrderFormatException(lineNumber, "bad quantity");

        decimal price;
        try
        {
            price = decimal.Parse(parts[2].Trim(), NumberStyles.AllowDecimalPoint, CultureInfo.InvariantCulture);
        }
        catch (Exception e) when (e is FormatException or OverflowException)
        {
            throw new OrderFormatException(lineNumber, "bad price", e);
        }
        return new OrderLine(item, quantity, price);
    }

    public static (List<OrderLine> Lines, List<string> Errors) ParseAll(IEnumerable<string> lines)
    {
        var good = new List<OrderLine>();
        var errors = new List<string>();
        int n = 0;
        foreach (string line in lines)
        {
            n++;
            if (string.IsNullOrWhiteSpace(line) || line.TrimStart().StartsWith('#')) continue;
            try
            {
                good.Add(Parse(line, n));
            }
            catch (OrderFormatException e)
            {
                errors.Add(e.Message);
            }
        }
        return (good, errors);
    }
}

unitTests:
string Problem(string line)
{
    try { Orders.Parse(line, 7); return "no error"; }
    catch (OrderFormatException e) { return e.Message; }
}

Test("good lines", () =>
{
    CheckEq(Orders.Parse("tea;2;2.50", 1), new OrderLine("tea", 2, 2.50m));
    CheckEq(Orders.Parse(" cake ; 1 ; 4 ", 2), new OrderLine("cake", 1, 4m));
});

Test("each problem", () =>
{
    CheckEq(Problem("tea;2"), "line 7: expected 3 fields");
    CheckEq(Problem("a;b;c;d"), "line 7: expected 3 fields");
    CheckEq(Problem(" ;2;1"), "line 7: missing item");
    CheckEq(Problem("tea;two;1"), "line 7: bad quantity");
    CheckEq(Problem("tea;0;1"), "line 7: bad quantity");
    CheckEq(Problem("tea;-3;1"), "line 7: bad quantity");
    CheckEq(Problem("tea;1001;1"), "line 7: bad quantity");
    CheckEq(Problem("tea;99999999999;1"), "line 7: bad quantity");
    CheckEq(Problem("tea;2;2,50"), "line 7: bad price");
    CheckEq(Problem("tea;2;-1"), "line 7: bad price");
});

Test("exception details", () =>
{
    try
    {
        Orders.Parse("tea;x;1", 3);
        Check(false, "should throw");
    }
    catch (OrderFormatException e)
    {
        CheckEq(e.LineNumber, 3);
        Check(e.InnerException is FormatException, "the FormatException should be kept as the inner exception");
    }
    try { Orders.Parse("tea;0;1", 4); }
    catch (OrderFormatException e) { Check(e.InnerException is null, "a range problem has no inner exception"); }
    CheckThrows<ArgumentNullException>(() => Orders.Parse(null!, 1));
    Check(new OrderFormatException(1, "x") is Exception, "should derive from Exception");
});

Test("parsing a whole file", () =>
{
    var (lines, errors) = Orders.ParseAll(new[] { "# orders", "tea;2;2.50", "", "cake;x;4", "mug;1;8", "  # note", "pen;1" });
    CheckEq(lines.Select(l => l.Item), new[] { "tea", "mug" });
    CheckEq(errors, new[] { "line 4: bad quantity", "line 7: expected 3 fields" });
});

